function equipment(){return `<section>${head(t('equipmentRegister'))}${card(t('equipmentRegister'),`<form id="equipmentForm" class="form"><input name="name" required placeholder="${t('equipment')}"><input name="location" placeholder="${t('location')}"><input name="serviceDate" type="date"><select name="status"><option value="operational">${t('operational')}</option><option value="serviceDue">${t('serviceDue')}</option><option value="outOfService">${t('outOfService')}</option></select><button class="btn primary">${t('add')}</button></form>${rows(state.equipment,(x,i)=>editingRow('equipment',i)?`<form class="form inline-edit" data-edit-form="equipment" data-index="${i}"><input name="name" required value="${esc(x.name)}"><input name="location" value="${esc(x.location)}"><input name="serviceDate" type="date" value="${esc(x.serviceDate)}"><select name="status"><option value="operational" ${x.status==='operational'?'selected':''}>${t('operational')}</option><option value="serviceDue" ${x.status==='serviceDue'?'selected':''}>${t('serviceDue')}</option><option value="outOfService" ${x.status==='outOfService'?'selected':''}>${t('outOfService')}</option></select>${editButtons()}</form>`:`<div class="row"><span><strong>${esc(x.name)}</strong><br><small class="muted">${esc(x.location)} · ${esc(x.serviceDate||'')}</small></span><span class="row-actions"><span class="pill">${t(x.status||'operational')}</span>${actions('equipment',i)}</span></div>`,'noEquipment')}`)}</section>`}
