document.querySelectorAll('[data-org-switch]').forEach(b=>b.addEventListener('click',async()=>{const target=state.restaurants.find(x=>x.id===b.dataset.orgSwitch);if(!target||(cloudSession()&&!cloudRestaurantAllowed(target))){alert(t('accessDenied'));return}if(switchRestaurant(state,b.dataset.orgSwitch,new Date(),!!cloudSession())){resetCloudSyncState();editing=null;page='dashboard';if(cloudSession())await syncCurrentWorkspaceOnOpen(true);render()}else alert(t('multiRequired'))}));
document.querySelectorAll('[data-org-remove]').forEach(b=>b.addEventListener('click',async()=>{if(!confirm(t('deleteConfirm')))return;
const type=b.dataset.orgRemove,id=b.dataset.id;if(type==='restaurant'){const entry=state.restaurants.find(x=>x.id===id);if(!entry)return;if(cloudSession()&&entry.cloudId){const organizationId=cloudOrganizationId();if(!organizationId){alert(t('identityLoadFailed'));return}try{await cloudFunction('remapro-admin',{action:'archive-restaurant',organizationId,restaurantId:entry.cloudId});if(cloudIdentity)cloudIdentity.restaurants=(cloudIdentity.restaurants||[]).filter(x=>x.id!==entry.cloudId)}catch{alert(t('cloudSyncFailed'));return}}if(!removeRestaurant(state,id)){alert(t('organizationDeleteBlocked'));return}render();return}const list=type==='manager'?state.managers:state.staffAccess,entry=list.find(x=>x.id===id);if(!entry)return;if(cloudSession()&&entry.cloudUserId){const organizationId=cloudOrganizationId(),cloudIds=cloudRestaurantIds(entry.restaurantIds);if(!organizationId||cloudIds.length!==entry.restaurantIds.length){alert(t('cloudMappingRequired'));return}try{await cloudFunction('remapro-admin',{action:'revoke-member',kind:type==='manager'?'manager':'staff',organizationId,userId:entry.cloudUserId,restaurantIds:cloudIds})}catch{alert(t('cloudSyncFailed'));return}}const ok=type==='manager'?removeManager(state,id):removeStaffAccess(state,id);if(!ok){alert(t('organizationDeleteBlocked'));return}render()}));
