document.getElementById('cloudForm')?.addEventListener('submit',e=>{e.preventDefault();
const d=new FormData(e.target),existing=cloudConfig(),previousScope=storageScope();if(!saveCloudConfig(d.get('url'),d.get('key')||existing.key)){alert(t('cloudInvalid'));return}if(previousScope&&!cloudSession()){resetCloudSyncState();setStorageScope('');replaceState(load())}cloudIdentity=null;cloudIdentityError='';render()});
document.getElementById('cloudDisconnect')?.addEventListener('click',()=>{disconnectCloud();resetCloudSyncState();setStorageScope('');replaceState(load());cloudIdentity=null;cloudIdentityError='';page='dashboard';render()});
document.getElementById('cloudTest')?.addEventListener('click',async e=>{if(!cloudSession()){alert(t('cloudLoginRequired'));return}const b=e.currentTarget;b.disabled=true;try{const ok=await hydrateCloudIdentity(false);alert(ok?t('cloudIdentityReady'):t('identityLoadFailed'))}finally{b.disabled=false}});
document.getElementById('aiForm')?.addEventListener('submit',async e=>{e.preventDefault();
const d=new FormData(e.target),q=String(d.get('question')||'').trim();if(!q)return;if(!cloudConfigured()){alert(t('aiCloudRequired'));return}if(!cloudSession()){alert(t('cloudLoginRequired'));return}const out=document.getElementById('aiAnswer');if(out)out.textContent=t('aiLoading');
const button=e.target.querySelector('button[type="submit"],button:not([type])');if(button)button.disabled=true;try{const data=await callRemaproAi({action:'chat',question:q,language:language(),context:buildAiContext(state),messages:aiMessages});aiAnswer=String(data.answer||t('aiUnavailable'));aiMessages=[...aiMessages,{role:'user',content:q},{role:'assistant',content:aiAnswer}].slice(-16)}catch{aiAnswer=t('aiUnavailable')}render()});
document.getElementById('aiBrief')?.addEventListener('click',()=>{const form=document.getElementById('aiForm'),field=form?.querySelector('[name=question]');if(!form||!field)return;field.value=t('dailyBriefingPrompt');form.requestSubmit()});
document.getElementById('stockPhotoAnalyze')?.addEventListener('click',async e=>{const input=document.getElementById('stockPhotoInput'),file=input?.files?.[0];if(!file){alert(t('selectPhoto'));return}if(file.size>8_000_000){alert(t('imageTooLarge'));return}if(!cloudConfigured()){alert(t('aiCloudRequired'));return}if(!cloudSession()){alert(t('cloudLoginRequired'));return}const b=e.currentTarget;b.disabled=true;
const old=b.textContent;b.textContent=t('aiLoading');try{const image=await fileToDataUrl(file),data=await callRemaproAi({action:'stock-photo',language:language(),image});if(!data?.product?.name)throw new Error('NO_PRODUCT');visionDraft=data.product;render()}catch{alert(t('photoAnalysisFailed'));b.disabled=false;b.textContent=old}});
document.getElementById('visionStockForm')?.addEventListener('submit',e=>{e.preventDefault();
const d=new FormData(e.target);if(!recordValidated(state,'stock',{name:d.get('name'),unit:d.get('unit'),qty:d.get('qty'),price:d.get('price'),min:d.get('min'),source:'photo'})){alert(t('invalidRecord'));return}visionDraft=null;persist();render()});
document.getElementById('invoicePhotoAnalyze')?.addEventListener('click',async e=>{const input=document.getElementById('invoicePhotoInput'),file=input?.files?.[0];if(!file){alert(t('selectPhoto'));return}if(file.size>8_000_000){alert(t('imageTooLarge'));return}if(!cloudConfigured()){alert(t('aiCloudRequired'));return}if(!cloudSession()){alert(t('cloudLoginRequired'));return}const b=e.currentTarget;b.disabled=true;
const old=b.textContent;b.textContent=t('aiLoading');try{const image=await fileToDataUrl(file),data=await callRemaproAi({action:'invoice-photo',language:language(),image});if(!Array.isArray(data?.items)||!data.items.length)throw new Error('NO_ITEMS');invoiceDraft=data;render()}catch{alert(t('invoiceAnalysisFailed'));b.disabled=false;b.textContent=old}});
document.getElementById('invoiceReviewForm')?.addEventListener('submit',e=>{e.preventDefault();
const d=new FormData(e.target),source=Array.isArray(invoiceDraft?.items)?invoiceDraft.items:[];
const selected=source.map((x,i)=>{if(!d.get('item_use_'+i))return null;return{name:String(d.get('item_name_'+i)||'').trim(),quantity:+d.get('item_qty_'+i),unit:String(d.get('item_unit_'+i)||'').trim(),unitPrice:+d.get('item_price_'+i)}}).filter(Boolean);if(!selected.length){alert(t('noInvoiceItems'));return}if(selected.some(x=>!x.name||!Number.isFinite(x.quantity)||x.quantity<=0||!Number.isFinite(x.unitPrice)||x.unitPrice<0)){alert(t('invoiceLineInvalid'));return}const result=integrateInvoiceReceipt(state,{supplier:d.get('supplier'),reference:d.get('reference'),date:d.get('date'),items:selected});if(!result){alert(t('duplicateInvoice'));return}invoiceDraft=null;persist();render();alert(t('invoiceIntegrated'))});
document.getElementById('invoiceReviewCancel')?.addEventListener('click',()=>{invoiceDraft=null;render()});
document.getElementById('exportData')?.addEventListener('click',()=>{const blob=new Blob([exportData(state)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`remaprohub-v27-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),0)});
document.getElementById('importData')?.addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;if(file.size>5_000_000){alert(t('importInvalid'));return}let contents;try{contents=await file.text()}catch{alert(t('importInvalid'));return}if(!confirm(t('importConfirm')))return;try{if(!importData(state,contents)){alert(t('importInvalid'));return}}catch{alert(t('importInvalid'));return}editing=null;page='dashboard';render();alert(t('importSuccess'))});
